SELECT
    ir.id AS intentId,
    ir.tenant_id AS tenantId,
    p.position AS position,
    ir.input_text AS inputText,
    ir.create_time AS createTime
FROM intent_request ir
INNER JOIN agent_task at ON at.intent_id = ir.id
LEFT JOIN person p ON p.user_id = ir.user_id AND p.tenant_id = ir.tenant_id


        ir.tenant_id = #{tenantId}


        AND at.pev_state = #{query.pevState}


        AND at.agent_role = #{query.agentRole}


        AND ir.create_time >= #{query.startTime}


        AND ir.create_time <= #{query.endTime}


GROUP BY ir.id, ir.tenant_id, p.position, ir.input_text, ir.create_time
ORDER BY ir.create_time DESC
